.editorial-img {
    flex: 1 1 400px;
    min-height: 300px;
    background-color: #334155;
    object-fit: cover;
    width: 100%;
}
.editorial-content {
    flex: 1 1 400px;
    padding: 48px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}
.editorial-title {
    font-size: 2rem;
    margin-bottom: 16px;
    line-height: 1.2;
}
.editorial-text {
    color: var(--text-secondary);
    margin-bottom: 32px;
    font-size: 1.125rem;
}

/* Footer */
.site-footer {
    background-color: #020617; /* Slate 950 */
    padding: 48px 0;
    margin-top: 64px;
    text-align: center;
    color: var(--text-secondary);
    border-top: 1px solid #1e293b;
